# add an MLB bet by hand on a finished game and on a pregame game
pg.click('#tabs button[data-t="mlb"]'); pg.wait_for_timeout(500)
pg.click('#m-open'); pg.wait_for_timeout(300)
print('league options:', pg.eval_on_selector_all('#m-lg option', 'els => els.filter(o => !o.hidden).map(o => o.value)'), 'selected', pg.evaluate('document.querySelector("#m-lg").value'))
pg.fill('#m-date', '2027-06-15'); pg.dispatch_event('#m-date', 'change'); pg.wait_for_timeout(900)
opts = pg.eval_on_selector_all('#m-game option', 'els => els.map(o => o.textContent)'); print('games:', len(opts), opts[1:4])
vals = pg.eval_on_selector_all('#m-game option', 'els => els.map(o => o.value)')
pg.select_option('#m-game', vals[1]); pg.select_option('#m-mkt', 'ml'); pg.wait_for_timeout(200)
print('sides:', pg.eval_on_selector_all('#m-side option', 'els => els.map(o => o.textContent)'))
pg.select_option('#m-side', 'home'); pg.fill('#m-odds', '-150'); pg.fill('#m-stake', '15'); pg.click('#m-save'); pg.wait_for_timeout(500)
pg.click('#m-open'); pg.wait_for_timeout(300); pg.select_option('#m-game', vals[len(vals) - 1]); pg.select_option('#m-mkt', 'total'); pg.wait_for_timeout(300)
print('prefilled total line:', pg.input_value('#m-line')); pg.fill('#m-stake', '10'); pg.click('#m-save'); pg.wait_for_timeout(500)
print('mine:', json.dumps(pg.evaluate('MINE.map(b => ({bet: b.bet, lg: b.league, res: b.result, game: b.game, odds: b.odds, away: b.away}))')))
print('mineboard:', pg.inner_text('#mineboard').replace('\n', ' | ')[:400])
rb = pg.evaluate('reportBuild()'); print('report mine:', json.dumps(rb['mine'])[:600]); print('report games (should hold no MLB):', len(rb['games']))
# a promoted rule becomes an AI-LOX
pg.evaluate('MLB.rule_stats.mlb_total_gap_under.lean_only = false; MLB.rule_stats.mlb_total_gap_under.p = 0.56; mlbRulesIn(); recompute(); mlbRender()')
pg.wait_for_timeout(300); print('AI-LOX after promotion:', json.dumps(pg.evaluate('BETS.filter(b => b.league === "MLB").map(b => ({bet: b.bet, stake: b.stake, odds: b.odds, date: b.date, hit: b.hit_rate}))'))[:700])
pg.screenshot(path='mlb_after.png', full_page=True)
